"use strict";
const $=id=>document.getElementById(id),t=OrionI18n.t;
const journeys=[[[2,4],[4,2],[1,1,3,2]],[[1,3],[3,1],[4,1,-2,3]],[[3,5],[5,3],[1,4,3,-2]],[[0,4],[4,0],[5,5,-3,-2]],[[2,5],[5,2],[2,1,2,4]],[[1,5],[5,1],[4,4,-3,-2]]];
let variant=OrionProgress.variant('coordinates'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget,stage=0,x=0,y=0,solved=false,hintDepth=0,hintOpen=false,state='ready',saveFailed=false;
function challenge(v=variant,s=stage){const a=journeys[v][s];return s<2?{target:a,start:null}:{target:[a[0]+a[2],a[1]+a[3]],start:a.slice(0,2),delta:a.slice(2)};}
function setAxis(axis,n){if(solved||!['x','y'].includes(axis)||!Number.isInteger(n)||n<0||n>5)return;if(axis==='x')x=n;else y=n;state='ready';render();}
function resetTrial(){x=y=0;solved=false;hintDepth=0;hintOpen=false;state='ready';saveFailed=false;$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('coordinates')){variant=v;stage=0;resetTrial();}
function check(){if(solved)return;const q=challenge();if(x!==q.target[0]||y!==q.target[1])state='wrong';else{solved=true;state='success';if(stage===2)saveFailed=!OrionProgress.earn('wayfinder');}render();if(solved&&stage<2)$('next').focus();}
function screen(a,b){return [50+a*45,265-b*45];}
function drawing(){const q=challenge(),[px,py]=screen(x,y);let s='';for(let i=0;i<=5;i++){const [a,b]=screen(i,i);s+=`<path d="M${a} 40V265M50 ${b}H275" stroke="#52717b"/><text x="${a}" y="287" text-anchor="middle">${i}</text><text x="30" y="${b+5}" text-anchor="middle">${i}</text>`;}if(q.start){const[a,b]=screen(...q.start);s+=`<path d="M${a} ${b-8}L${a+8} ${b}L${a} ${b+8}L${a-8} ${b}Z" fill="#eec974"/>`;}return `<svg viewBox="0 0 330 310" role="img" aria-label="${t(`Your blue marker is at (${x}, ${y}). X increases right; Y increases up.`,`你的藍色標記在 (${x}, ${y})。X 向右增加，Y 向上增加。`)}"><g fill="#edf1df" font-size="15">${s}<text x="300" y="270">x →</text><text x="40" y="22">y ↑</text></g><path d="M50 265H${px}V${py}" stroke="#8ed9ed" stroke-width="3" fill="none" stroke-dasharray="5 4"/><circle cx="${px}" cy="${py}" r="9" fill="#71d5ef" stroke="white" stroke-width="3"/></svg>`;}
function moveText(q){return t(`Start at (${q.start}). Move ${Math.abs(q.delta[0])} ${q.delta[0]>0?'right':'left'} and ${Math.abs(q.delta[1])} ${q.delta[1]>0?'up':'down'}. Mark where the treasure is.`,`從 (${q.start}) 出發，向${q.delta[0]>0?'右':'左'} ${Math.abs(q.delta[0])} 格，再向${q.delta[1]>0?'上':'下'} ${Math.abs(q.delta[1])} 格。標出寶藏位置。`);}
function hints(){const q=challenge();return[t('Watch the blue marker while moving one slider at a time. Where is (0, 0)?','每次移動一條滑桿，觀察藍色標記。(0, 0) 在哪裏？'),t('The first number is x: across. The second is y: up. Swapping them usually changes the place.','第一個數是 x：橫向。第二個是 y：向上。交換兩個數，通常會改變位置。'),t(`For this seal, mark (${q.target[0]}, ${q.target[1]}): ${q.target[0]} right and ${q.target[1]} up from the origin.`,`這道封印要標出 (${q.target[0]}, ${q.target[1]})：從原點向右 ${q.target[0]} 格、向上 ${q.target[1]} 格。`)];}
function render(){const q=challenge(),complete=solved&&stage===2,p=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Star Map Vault · Orion','星圖寶庫 · Orion');$('stageTitle').textContent=t(`Map ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 幅星圖 · 題組 ${variant+1}`);$('sceneStatus').textContent=t(`Map seals · ${p} / 3`,`星圖封印 · ${p} / 3`);$('seals').textContent=Array.from({length:3},(_,i)=>i<p?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);$('diagram').innerHTML=drawing();for(const a of ['x','y']){$(a).value=a==='x'?x:y;$(a).disabled=solved;$(a+'Value').textContent=a==='x'?x:y;} $('goal').textContent=q.start?moveText(q):t(`Find the treasure at (${q.target[0]}, ${q.target[1]}). Move the blue marker, then check.`,`找出 (${q.target[0]}, ${q.target[1]}) 的寶藏。移動藍色標記，再檢查。`);$('reading').textContent=t(`Your marker: (${x}, ${y})`,`你的標記：(${x}, ${y})`);$('landmark').textContent=q.start?t(`Gold diamond: starting point (${q.start}).`,`金色菱形：起點 (${q.start})。`):t('Origin (0, 0): bottom-left crossing.','原點 (0, 0)：左下方交點。');const messages={ready:['Explore the map, then check your marker.','探索星圖，再檢查標記。'],wrong:['The vault is still quiet. Compare each coordinate and try again.','寶庫仍然安靜。比較兩個座標，再試一次。'],success:['A map seal shines! Your position matches.','星圖封印亮起來了！位置吻合。']};$('feedback').textContent=t(...messages[state]);$('check').hidden=solved;$('retry').hidden=solved;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=solved;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintOpen));$('hints').hidden=!hintOpen;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('')+`<li class="close-clues"><button data-close>${t('Close clues','關閉提示')}</button></li>`;$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('wayfinder')?t('Wayfinder Sigil saved in your collection.','尋路符印已存入收藏。'):'';}
for(const a of ['x','y'])$(a).oninput=e=>setAxis(a,Number(e.target.value));
$('hints').onclick=e=>{if(e.target.closest('button[data-close]')){hintOpen=false;render();$('hint').focus();}};window.addEventListener('keydown',e=>{if(e.key==='Escape'&&hintOpen){hintOpen=false;render();$('hint').focus();}});$('check').onclick=check;$('retry').onclick=()=>{if(!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();};$('hint').onclick=()=>{hintDepth=Math.min(3,hintDepth+1);hintOpen=true;render();};
$('replay').onclick=()=>{const v=OrionProgress.nextVariant('coordinates',variant);observedVariant=OrionProgress.variant('coordinates');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('wayfinder');render();};function syncProgress(){const v=OrionProgress.variant('coordinates'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('wayfinder')&&!saveFailed)resetMission();else render();}window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);resetMission();OrionI18n.apply();
